import{_ as t,o,c as a,a2 as s}from"./chunks/framework.vLhlLNVn.js";const b=JSON.parse('{"title":"How do I choose the dashboard version and how to reach it?","description":"","frontmatter":{"order":3,"adapter":"esphome","editLink":"https://github.com/DrozmotiX/ioBroker.esphome/edit/main/docs/en/02.anleitungen/03.dashboard-nutzen.md"},"headers":[],"relativePath":"adapter/esphome/anleitungen/dashboard-nutzen.md","filePath":"adapter/esphome/anleitungen/dashboard-nutzen.md","lastUpdated":1795562976000}'),d={name:"adapter/esphome/anleitungen/dashboard-nutzen.md"};function n(i,e,h,r,l,c){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="how-do-i-choose-the-dashboard-version-and-how-to-reach-it" tabindex="-1">How do I choose the dashboard version and how to reach it? <a class="header-anchor" href="#how-do-i-choose-the-dashboard-version-and-how-to-reach-it" aria-label="Permalink to &quot;How do I choose the dashboard version and how to reach it?&quot;">​</a></h1><p><a id="choose-update-esphome-dashboard-version"></a></p><h2 id="how-do-i-choose-or-update-the-esphome-dashboard-version-including-older-ones" tabindex="-1">How do I choose or update the ESPHome dashboard version, including older ones? <a class="header-anchor" href="#how-do-i-choose-or-update-the-esphome-dashboard-version-including-older-ones" aria-label="Permalink to &quot;How do I choose or update the ESPHome dashboard version, including older ones?&quot;">​</a></h2><p>You select the version in the instance settings under &quot;ESPHome Dashboard version&quot; or type it there. After saving, the instance restarts and installs exactly this version. The default is <code>2026.6.5</code>.</p><p>The adapter picks everything else ESPHome needs to match. From ESPHome 2026.7.0 on it also installs ESPHome Device Builder, which provides the dashboard there. ESPHome brings the matching Pillow version itself.</p><h3 id="how-to-do-it" tabindex="-1">How to do it <a class="header-anchor" href="#how-to-do-it" aria-label="Permalink to &quot;How to do it&quot;">​</a></h3><ol><li>Open the instance settings, tab &quot;ESPHome Dashboard&quot;.</li><li>Pick a version from the list under &quot;ESPHome Dashboard version&quot;. If it is missing, for example an older one or a beta, type it in, e.g. <code>2026.5.3</code>.</li><li>Save. The instance restarts and installs the version. This takes a few minutes, meanwhile the ESPHome tab shows the start log.</li><li>The log then shows &quot;Starting ESPHome Dashboard. ESPHome version: …&quot; with the installed versions of ESPHome, Pillow and Device Builder.</li></ol><p>The list comes from GitHub when the instance starts and holds the 30 or so newest releases. If GitHub cannot be reached, the adapter uses the list from the last successful call. <code>esphome.0._ESPHomeDashboard.selectedVersion</code> shows the version in use, <code>esphome.0._ESPHomeDashboard.newestVersion</code> the newest one on GitHub.</p><h3 id="what-does-always-last-available-mean" tabindex="-1">What does &quot;Always last available&quot; mean? <a class="header-anchor" href="#what-does-always-last-available-mean" aria-label="Permalink to &quot;What does &quot;Always last available&quot; mean?&quot;">​</a></h3><p>With it, the adapter installs the newest ESPHome version at every start. If a release comes out that cannot be installed, the dashboard stops starting without any change on your side. Select a fixed version instead and change it deliberately to update.</p><h3 id="what-is-under-advanced" tabindex="-1">What is under &quot;Advanced&quot;? <a class="header-anchor" href="#what-is-under-advanced" aria-label="Permalink to &quot;What is under &quot;Advanced&quot;?&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>Purpose</th></tr></thead><tbody><tr><td>&quot;Pillow version&quot;</td><td><code>Auto Detect</code></td><td>ESPHome installs the matching version itself. Use a fixed version only if pip asks for exactly that one in the log.</td></tr><tr><td>&quot;ESPHome Device Builder version&quot;</td><td><code>Auto Detect</code></td><td>newest version that supports the selected ESPHome version</td></tr><tr><td>&quot;Python version&quot;</td><td><code>3.13.2</code></td><td>a version like <code>3.13.2</code> or a range like <code>3.12</code>. A change creates the Python environment again at the next start.</td></tr></tbody></table><p>With &quot;Use Docker Integration (Beta)&quot; these three fields are hidden. The adapter then starts the official ESPHome image in the selected version.</p><p>If the dashboard itself reports an update, that only affects its own display. Which version runs is decided by the adapter setting alone.</p><p><strong>See also:</strong> <a href="./../fehlerbehebung/dashboard-startet-nicht#dashboard-not-start-pillow-esphome">Why does the dashboard not start?</a></p><p><a id="use-external-esphome-dashboard-instead"></a></p><h2 id="how-do-i-use-an-external-esphome-dashboard-instead-of-the-built-in-one" tabindex="-1">How do I use an external ESPHome dashboard instead of the built-in one? <a class="header-anchor" href="#how-do-i-use-an-external-esphome-dashboard-instead-of-the-built-in-one" aria-label="Permalink to &quot;How do I use an external ESPHome dashboard instead of the built-in one?&quot;">​</a></h2><p><em>This section is still being written.</em></p><p><a id="show-dashboard-admin-tab-using"></a></p><h2 id="how-do-i-show-the-dashboard-in-the-admin-tab-when-using-https" tabindex="-1">How do I show the dashboard in the admin tab when using HTTPS? <a class="header-anchor" href="#how-do-i-show-the-dashboard-in-the-admin-tab-when-using-https" aria-label="Permalink to &quot;How do I show the dashboard in the admin tab when using HTTPS?&quot;">​</a></h2><p><em>This section is still being written.</em></p>',21)])])}const m=t(d,[["render",n]]);export{b as __pageData,m as default};
